1	package snapshot
2	
3	import (
4		"bytes"
5		"encoding/binary"
6		"errors"
7		"fmt"
8		"io/fs"
9		"os"
10		"path/filepath"
11		"runtime"
12		"sync"
13		"testing"
14		"time"
15	)
16	
17	// copyChain duplicates a completed backup artifact directory file by file.
18	// Completed artifacts hold flat files only (segments, manifest, rings).
19	func copyChain(t *testing.T, src string) string {
20		t.Helper()
21		dst := filepath.Join(t.TempDir(), filepath.Base(src))
22		if err := os.MkdirAll(dst, 0o700); err != nil {
23			t.Fatal(err)
24		}
25		entries, err := os.ReadDir(src)
26		if err != nil {
27			t.Fatal(err)
28		}
29		for _, e := range entries {
30			if e.IsDir() {
31				t.Fatalf("completed artifact contains directory %q", e.Name())
32			}
33			data, err := os.ReadFile(filepath.Join(src, e.Name()))
34			if err != nil {
35				t.Fatal(err)
36			}
37			if err := os.WriteFile(filepath.Join(dst, e.Name()), data, 0o600); err != nil {
38				t.Fatal(err)
39			}
40		}
41		return dst
42	}
43	
44	// restoreCheckpoint restores art into a fresh target, closes it, reopens and
45	// returns the reopened store, after asserting the live state equals want.
46	func restoreCheckpoint(t *testing.T, art string, want []KVPair, snaps uint64) (*Store, string) {
47		t.Helper()
48		target := filepath.Join(t.TempDir(), "restored")
49		rs, err := Restore(art, target)
50		if err != nil {
51			t.Fatalf("Restore: %v", err)
52		}
53		assertSamePairs(t, allPairs(t, rs), want, "restored live state")
54		if n := rs.Stats().Snapshots; n != snaps {
55			t.Fatalf("live snapshot count = %d, want %d", n, snaps)
56		}
57		if err := rs.Close(); err != nil {
58			t.Fatal(err)
59		}
60		s2, err := Open(target)
61		if err != nil {
62			t.Fatal(err)
63		}
64		assertSamePairs(t, allPairs(t, s2), want, "restored reopened state")
65		if n := s2.Stats().Snapshots; n != snaps {
66			t.Fatalf("reopened snapshot count = %d, want %d", n, snaps)
67		}
68		return s2, target
69	}
70	
71	func TestIncrementalChainRoundtrip(t *testing.T) {
72		s := openStore(t, tempDir(t))
73		if err := s.CommitBatch([]BatchOp{
74			{Key: "alpha", Value: []byte("one")},
75			{Key: "empty", Value: nil},
76			{Key: "gone", Value: []byte("x")},
77		}); err != nil {
78			t.Fatal(err)
79		}
80		if err := s.CommitBatch([]BatchOp{
81			{Key: "gone", Delete: true},
82			{Key: "multi", Value: []byte("first")},
83			{Key: "multi", Value: []byte("second")}, // within-batch last write wins
84		}); err != nil {
85			t.Fatal(err)
86		}
87		if _, err := s.Snapshot(); err != nil {
88			t.Fatal(err)
89		}
90	
91		chain := filepath.Join(t.TempDir(), "chain")
92		if err := s.Backup(chain); err != nil {
93			t.Fatal(err)
94		}
95		type stage struct {
96			art   string
97			pairs []KVPair
98			snaps uint64
99		}
100		stages := []stage{{copyChain(t, chain), allPairs(t, s), s.Stats().Snapshots}}
101	
102		// Ring 1: update, delete, add; put-then-delete and delete-then-put batch
103		// semantics straddle the ring boundary.
104		if err := s.CommitBatch([]BatchOp{
105			{Key: "alpha", Value: []byte("two")},
106			{Key: "empty", Delete: true},
107			{Key: "pd", Value: []byte("v")},
108			{Key: "pd", Delete: true}, // put-then-delete: absent after
109			{Key: "dp", Delete: true},
110			{Key: "dp", Value: []byte("back")}, // delete-then-put: present
111		}); err != nil {
112			t.Fatal(err)
113		}
114		if _, err := s.Snapshot(); err != nil {
115			t.Fatal(err)
116		}
117		if err := s.BackupIncremental(chain); err != nil {
118			t.Fatalf("incremental 1: %v", err)
119		}
120		stages = append(stages, stage{copyChain(t, chain), allPairs(t, s), s.Stats().Snapshots})
121	
122		// Ring 2: overwrite one of ring 1's keys, touch a head key, add more.
123		if err := s.CommitBatch([]BatchOp{
124			{Key: "alpha", Value: []byte("three")},
125			{Key: "multi", Delete: true},
126			{Key: "new", Value: []byte("n")},
127		}); err != nil {
128			t.Fatal(err)
129		}
130		if _, err := s.Snapshot(); err != nil {
131			t.Fatal(err)
132		}
133		if err := s.BackupIncremental(chain); err != nil {
134			t.Fatalf("incremental 2: %v", err)
135		}
136		stages = append(stages, stage{copyChain(t, chain), allPairs(t, s), s.Stats().Snapshots})
137	
138		// Every prefix of the chain restores to exactly its own watermark state,
139		// live and after reopen.
140		var lastDir string
141		for i, st := range stages {
142			rs, dir := restoreCheckpoint(t, st.art, st.pairs, st.snaps)
143			lastDir = dir
144			if i == len(stages)-1 {
145				// Counting continues from the preserved cumulative count.
146				if _, err := rs.Snapshot(); err != nil {
147					t.Fatal(err)
148				}
