336		if err := s.Backup(chain); err != nil {
337			t.Fatal(err)
338		}
339	
340		// Drive an export while commits keep landing; then verify the artifact
341		// restores to some internally consistent, fixed watermark state (not a
342		// mixture) by restoring twice and comparing byte-for-byte.
343		var wg sync.WaitGroup
344		stop := make(chan struct{})
345		wg.Add(1)
346		go func() {
