	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		name := e.Name()
		if isMergeTempName(name, base, verifyStagePrefix) {
			staging = append(staging, name)
		}
		if isMergeTempName(name, base, verifyTrashPrefix) {
			trash = append(trash, name)
		}
	}
