// buildStagedChain writes a full head and one ring per op group (each preceded
// by one snapshot), returning the chain path and a snapshot of the chain
// directory after every stage: head first, then head plus rings 1..n. Each
// copy restores to the exact state and snapshot count at that stage.
func buildStagedChain(t *testing.T, s *Store, parent string, ringOps [][]BatchOp) (string, []struct {
	dir   string
	pairs []KVPair
	snaps uint64
}) {
	t.Helper()
	chain := filepath.Join(parent, "chain")
	if err := s.Backup(chain); err != nil {
		t.Fatalf("backup: %v", err)
	}
	var stages []struct {
		dir   string
		pairs []KVPair
		snaps uint64
	}
	stages = append(stages, struct {
		dir   string
		pairs []KVPair
		snaps uint64
	}{copyChain(t, chain), allPairs(t, s), s.Stats().Snapshots})
	for _, ops := range ringOps {
		if err := s.CommitBatch(ops); err != nil {
			t.Fatal(err)
		}
		if _, err := s.Snapshot(); err != nil {
			t.Fatal(err)
		}
		if err := s.BackupIncremental(chain); err != nil {
			t.Fatalf("incremental: %v", err)
		}
		stages = append(stages, struct {
			dir   string
			pairs []KVPair
			snaps uint64
		}{copyChain(t, chain), allPairs(t, s), s.Stats().Snapshots})
	}
	return chain, stages
}

