426	// open-time counterpart of installDegradedChain's commit:
427	//
428	//   - chain missing, retired copy present: the kill landed between the two
429	//     commit renames; move the whole old chain back (the swap is undone).
430	//   - chain present, retired copy present: the replacement chain is installed;
431	//     move the damaged suffix out of the retired copy into a quarantine
432	//     directory and remove the retired copy, finishing the isolation.
433	//   - orphaned staging directories are pure debris and are removed.
434	//
435	// It is best-effort, like the other open-time sweeps, and stands down while a
436	// live lease holder operates on the chain, so it never takes apart a swap an
437	// in-flight operation is about to finish.
438	// guardLease makes the sweep stand down while a live lease holder operates on
439	// the chain (Open holds no lease itself and must never take apart another
440	// process's in-flight swap); the lease-holding chain operations pass false.
441	func sweepVerifyDebris(chainDir string, guardLease bool) {
442		parent := filepath.Dir(chainDir)
443		base := filepath.Base(chainDir)
